WITH with_prev AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM device_readings), flagged AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL '15' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM with_prev), sessions_device_readings AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT burst_id, COUNT(DISTINCT device_code) AS distinct_device_codes, BIT_AND(status_bits) AS status_bits_bit_and, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, STDDEV_SAMP(pressure) AS pressure_stddev, MAX(prev_reading_ts) AS last_prev_reading_ts, BIT_OR(status_bits) AS status_bits_bit_or, GROUPING_ID() AS grouping_level FROM sessions_device_readings GROUP BY CUBE (burst_id);
